def inr_format(n):
    s = str(n)
    if len(s) <= 3:
        return s
    parts = []
    while len(s) > 2:
        parts.insert(0, s[-2:])
        s = s[:-2]
    if parts:
        parts.insert(0, parts[0])
    return ','.join(parts) + ',' + s

